package com.dabble.protomorphic

import com.squareup.wire.FieldEncoding
import com.squareup.wire.ProtoAdapter
import com.squareup.wire.Syntax
import kotlin.reflect.KClass

/**
 * The adapter of a message generated by protoc-gen-protomorphic-kotlin: a Wire [ProtoAdapter] that
 * also knows the message's [fields] by name, so values can be read and written by field path
 * ([ProtoFields]) without reflection, on every target.
 */
public abstract class MessageAdapter<E : Any>(
    fieldEncoding: FieldEncoding,
    type: KClass<*>?,
    typeUrl: String?,
    syntax: Syntax,
    identity: E?,
    sourceFile: String?,
) : ProtoAdapter<E>(fieldEncoding, type, typeUrl, syntax, identity, sourceFile) {
    /** The message's fields by proto name (e.g. "redirect_url"). */
    public abstract val fields: Map<String, ProtoField>
}

/** One field of a message: its number and, for a message-typed field, that message's adapter. */
public class ProtoField(
    public val number: Int,
    private val messageAdapter: (() -> MessageAdapter<*>)? = null,
) {
    /** The field's message type, or null for scalars, enums, maps and well-known types. */
    public val message: MessageAdapter<*>? get() = messageAdapter?.invoke()
}
